    length(u) == 16 || error("FK structural sensitivity vector must have length 16")
    dx = zeros(8)
    fx = zeros(8, 8)
    fu = zeros(8, 16)
    fxx = zeros(8, 8, 8)
    fxu = zeros(8, 8, 16)
    fuu = zeros(8, 16, 16)
