    fk_rhs_sensitivity_component_6!(dx, fx, fu, fxx, fxu, fuu, x, u)
    fk_rhs_sensitivity_component_7!(dx, fx, fu, fxx, fxu, fuu, x, u)
    fk_rhs_sensitivity_component_8!(dx, fx, fu, fxx, fxu, fuu, x, u)
